<script setup lang="ts">
import RecordSelect from './RecordSelect.vue'
import {ref,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage} from 'element-plus'
import {get,post,put} from '../api/http'
import type {Row} from '../api/types'
import {useAuth} from '../stores/auth'
import {usePagedResource} from '../composables/usePagedResource'
import {useMutation,confirmAction,number,money,dateTime} from '../composables/useResource'
import ExchangeActions from './ExchangeActions.vue'
import DataTable from './DataTable.vue'
import ResourceState from './ResourceState.vue'
import StatusTag from './StatusTag.vue'
const emit=defineEmits<{changed:[]}>(),auth=useAuth(),route=useRoute(),status=ref(String(route.query.status||''))
const list=usePagedResource(()=>`/stocktakes?status=${status.value}`),dialog=ref(false),detail=ref<Row|null>(null),form=ref<any>({warehouse_id:'',note:'',items:[]}),reviewComment=ref('')
const editable=computed(()=>auth.can('stocktake:write')&&(!detail.value||['DRAFT','REJECTED'].includes(detail.value.status))&&(!detail.value||String(detail.value.applicant_id)===String(auth.user?.id)||auth.can('*')))
const {saving,run}=useMutation(async()=>{await list.load();emit('changed')})
async function open(id:any){if(!id)return;try{detail.value=await get<Row>(`/stocktakes/${id}`);form.value=JSON.parse(JSON.stringify(detail.value));reviewComment.value='';dialog.value=true}catch{}}
function create(correction?:Row){detail.value=null;form.value={warehouse_id:correction?.warehouse_id||'',correction_of:correction?.id,note:correction?`纠正 ${correction.code}`:'',items:[]};dialog.value=true}
async function snapshot(line:Row){line.snapshot_revision=null;line.counted_quantity=null;if(!form.value.warehouse_id||!line.material_id)return;try{const data=await get<Row>(`/stocktakes/snapshot?warehouse_id=${form.value.warehouse_id}&material_id=${line.material_id}`);Object.assign(line,{snapshot_quantity:data.quantity,snapshot_revision:data.revision,has_positive_price:data.has_positive_price,unit:data.unit,snapshot_average_price:data.average_price})}catch{}}
async function save(){const id=detail.value?.id;if(await run(async()=>{const body={warehouse_id:form.value.warehouse_id,note:form.value.note,correction_of:form.value.correction_of,expected_version:detail.value?.version,items:form.value.items.map((i:Row)=>({material_id:i.material_id,snapshot_revision:i.snapshot_revision,counted_quantity:i.counted_quantity,gain_unit_price:i.gain_unit_price,reason:i.reason}))};const result=await (id?put<Row>(`/stocktakes/${id}`,body):post<Row>('/stocktakes',body));await open(result.id)},'草稿已保存，库存未改变')){}}
async function action(type:string,decision?:string){const d=detail.value;if(!d)return;let body:any={expected_version:d.version};if(type==='review'){body={...body,decision,comment:reviewComment.value};if(decision==='APPROVED'&&!await confirmAction('审核通过后将按当前账面快照调整库存并生成独立盘点流水，不能直接编辑。确认已核对？'))return}if(type==='refresh'){if(!await confirmAction('重新读取当前账面，保留实盘数量。请再次人工核对实盘、差异及原因后保存提交。'))return;body.confirm_snapshot=true}if(type==='withdraw'){if(!reviewComment.value.trim()){ElMessage.warning('请填写撤回原因');return}body.reason=reviewComment.value}await run(async()=>{await post(`/stocktakes/${d.id}/${type}`,body);await open(d.id)},'操作成功')}
watch(status,()=>list.paging.page=1)
watch(()=>route.query.stocktake_id,id=>{if(id)open(id)},{immediate:true})
</script>
<template><div class="subheading"><h3>库存盘点</h3><ExchangeActions entity="stocktakes" :filters="{q:list.paging.q,status}"/><el-button v-if="auth.can('stocktake:write')" type="primary" @click="create()">＋ 新建盘点单</el-button></div><el-alert class="mb" :closable="false" type="info" title="保存、提交不改库存；独立审核通过才入账。盘点期间账面有变化必须重新确认。盘点差异单独记录，不计入项目成本。"/><ResourceState :loading="list.loading.value" :error="list.error.value" @retry="list.load"><DataTable :rows="list.data.value" :remote="list.paging" @page="list.onPage" @size="list.onSize" @search="list.onSearch" :columns="[{key:'code',label:'盘点单号'},{key:'warehouse_name',label:'仓库'},{key:'status',label:'状态',status:true},{key:'applicant_name',label:'制单人'},{key:'submitted_at',label:'提交时间',date:true},{key:'reviewer_name',label:'审核人'},{key:'reviewed_at',label:'审核时间',date:true}]"><template #toolbar><el-select v-model="status" clearable placeholder="全部状态" style="width:150px"><el-option v-for="s in [{v:'DRAFT',n:'草稿'},{v:'PENDING',n:'待审核'},{v:'REJECTED',n:'驳回'},{v:'APPROVED',n:'已生效'}]" :key="s.v" :label="s.n" :value="s.v"/></el-select></template><template #actions="{row}"><el-button link type="primary" @click="open(row.id)">查看 / 处理</el-button></template></DataTable></ResourceState>
<el-dialog v-model="dialog" :title="detail?`盘点单 · ${detail.code}`:'新建盘点单'" width="1000px" :close-on-click-modal="false"><template v-if="dialog"><div v-if="detail" class="mb"><StatusTag :value="detail.status"/> · 制单 {{detail.applicant_name}} · 版本 {{detail.version}}<p v-if="detail.correction_of">明确纠正原单：<el-button link type="primary" @click="open(detail.correction_of)">{{detail.correction_code}}</el-button></p></div><el-form label-position="top"><div class="form-grid"><el-form-item label="盘点仓库 *"><RecordSelect v-model="form.warehouse_id" :disabled="!editable||!!detail" @change="form.items=[]" entity="warehouses"/></el-form-item><el-form-item label="备注"><el-input v-model="form.note" :disabled="!editable" maxlength="1000"/></el-form-item></div><div class="subheading"><h3>材料明细</h3><el-button v-if="editable" :disabled="!form.warehouse_id" @click="form.items.push({material_id:'',counted_quantity:null,reason:''})">＋ 添加材料</el-button></div><el-empty v-if="!form.items.length" description="请选择仓库并添加实际盘点的材料"/><div class="mobile-form-lines"><section v-for="(line,index) in form.items" :key="index" class="mobile-form-line"><div class="subheading"><h3>盘点材料 {{Number(index)+1}}</h3><el-button v-if="editable" type="danger" plain @click="form.items.splice(index,1)">删除</el-button></div><div class="form-grid"><el-form-item label="材料 *"><RecordSelect v-model="line.material_id" :disabled="!editable||!!line.id" @change="snapshot(line)" entity="materials"/></el-form-item><el-form-item label="账面数量 / 差异"><span>{{number(line.snapshot_quantity)}} {{line.unit}} / {{line.counted_quantity===null?'未填写':number(Number(line.counted_quantity)-Number(line.snapshot_quantity))}}</span></el-form-item><el-form-item label="实盘数量 *"><el-input-number v-model="line.counted_quantity" :disabled="!editable" :min="0" :precision="3" controls-position="right" style="width:100%"/></el-form-item><el-form-item label="差异原因"><el-input v-model="line.reason" :disabled="!editable" maxlength="1000" placeholder="有差异必填"/></el-form-item><el-form-item v-if="(line.price_required||line.has_positive_price===false)&&Number(line.counted_quantity)>Number(line.snapshot_quantity)" label="盘盈明确单价 *（无可用账面价格）"><el-input-number v-model="line.gain_unit_price" :disabled="!editable" :min="0.0001" :precision="4" style="width:100%"/></el-form-item><el-form-item v-if="line.adjustment_amount!==undefined&&line.adjustment_amount!==null" label="实际调整金额（元）"><span>{{money(line.adjustment_amount)}}</span></el-form-item></div></section></div><p class="field-hint">盘盈按当前移动加权价格；无正数价格须明确录入。盘亏按账面移动加权价值，全量盘亏吸收尾差。审核前会同时检查数量、金额和库存版本。</p><template v-if="detail?.status==='PENDING'"><el-form-item label="审核意见 / 撤回原因"><el-input v-model="reviewComment" type="textarea" maxlength="1000"/></el-form-item></template></el-form><template v-if="detail?.records?.length"><h3>操作记录</h3><ul><li v-for="r in detail.records" :key="r.id">{{dateTime(r.created_at)}} · {{r.operator_name}} · {{({SAVED:'保存草稿',REFRESHED:'刷新快照',SUBMITTED:'提交审核',WITHDRAWN:'撤回',APPROVED:'审核生效',REJECTED:'驳回'} as Record<string,string>)[r.decision]||r.decision}} · {{r.comment}}</li></ul></template></template><template #footer><el-button @click="dialog=false">关闭</el-button><template v-if="editable"><el-button v-if="detail" :loading="saving" @click="action('refresh')">刷新账面快照</el-button><el-button type="primary" :loading="saving" @click="save">保存草稿</el-button><el-button v-if="detail" :loading="saving" @click="action('submit')">提交已保存版本</el-button></template><el-button v-if="detail?.status==='PENDING'&&String(detail.applicant_id)===String(auth.user?.id)&&auth.can('stocktake:write')" :loading="saving" @click="action('withdraw')">撤回</el-button><template v-if="detail?.status==='PENDING'&&auth.can('stocktake:approve')&&String(detail.applicant_id)!==String(auth.user?.id)"><el-button type="danger" :loading="saving" @click="action('review','REJECTED')">驳回</el-button><el-button type="primary" :loading="saving" @click="action('review','APPROVED')">审核并调整库存</el-button></template><el-button v-if="detail?.status==='APPROVED'&&auth.can('stocktake:write')" @click="create(detail)">创建关联纠正单</el-button></template></el-dialog></template>
